#include "core/InstrumentBody.h"
#include "core/InstrumentBodyFilter.h"
#include <algorithm>
#include <array>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <limits>
#include <string>

using cs80::body::InstrumentBody;
using cs80::body::InstrumentBodyFilter;
namespace {
constexpr float nan = std::numeric_limits<float>::quiet_NaN();
constexpr float inf = std::numeric_limits<float>::infinity();
constexpr float maxf = std::numeric_limits<float>::max();
constexpr double nand = std::numeric_limits<double>::quiet_NaN();
constexpr double infd = std::numeric_limits<double>::infinity();
constexpr double maxd = std::numeric_limits<double>::max();
struct Rate { double internal, host; };
constexpr Rate rates[] = {
    {-infd, -infd}, {-1, -1}, {0, 0}, {7999, 2000}, {8000, 8000},
    {44100, 44100}, {96000, 48000}, {192000, 96000}, {1536000, 192000},
    {maxd, maxd}, {nand, nand}, {infd, infd}, {8000, 48000}, {96000, nand}
};
struct Note { float key, velocity, brightness, decay, size; };
constexpr Note notes[] = {
    {0, 0, 0, .25f, .5f}, {127, 1, 1, 4, 2.5f},
    {60, .2f, .65f, 1, 1}, {-maxf, -maxf, -maxf, -maxf, -maxf},
    {maxf, maxf, maxf, maxf, maxf}, {nan, nan, nan, nan, nan},
    {inf, inf, inf, inf, inf}, {-inf, -inf, -inf, -inf, -inf},
    {60.5f, .99f, .1f, .3f, .51f}
};
constexpr float frequencies[] = {8.1758f, 32.7032f, 261.6256f, 12543.854f,
    1e-30f, maxf, -1, 0, nan, inf, -inf};
constexpr float controls[] = {0, 1, .5f, -maxf, maxf, nan, inf, -inf};
constexpr float cutoffs[] = {8, 200, 1000, 20000, -maxf, maxf, nan, inf, -inf};
constexpr float qs[] = {.5f, 4, 1, -maxf, maxf, nan, inf, -inf};
std::uint64_t bodySamples = 0, filterSamples = 0, checks = 0, failures = 0;
std::uint64_t resets = 0, noteOns = 0, prepares = 0;
double bodyPeak = 0, filterPeak = 0;
void check(bool value, const char* label) {
    ++checks;
    if (!value && failures++ < 12) std::fprintf(stderr, "FAIL %s\n", label);
}
void bodySample(float x) {
    ++bodySamples;
    check(std::isfinite(x), "body finite");
    check(std::abs(x) < 4.0f, "body bounded");
    bodyPeak = std::max(bodyPeak, std::abs(double(x)));
}
void filterSample(float x) {
    ++filterSamples;
    check(std::isfinite(x), "filter finite");
    filterPeak = std::max(filterPeak, std::abs(double(x)));
}

__attribute__((noinline)) int addressControl(int index) {
    volatile int* memory = new int[2];
    memory[0] = 1;
    memory[1] = 2;
    const int value = memory[index];
    delete[] memory;
    return value;
}
__attribute__((noinline)) int undefinedControl(int value) {
    volatile int addition = 1;
    return value + addition;
}
}

int main(int argc, char** argv) {
    if (argc > 1 && std::string(argv[1]) == "--address-control")
        return addressControl(2);
    if (argc > 1 && std::string(argv[1]) == "--undefined-control")
        return undefinedControl(std::numeric_limits<int>::max());
    // Default construction, before prepare(), has valid zero-state storage.
    InstrumentBody body;
    InstrumentBodyFilter filter;
    check(body.tick(440, .5f, 0) == 0, "default body silent");
    check(filter.tickFrozen(0) == 0, "default frozen filter silent");
    int matrixCases = 0;
    for (int modelIndex = 0; modelIndex < 22; ++modelIndex) {
        const int model = modelIndex < 20 ? modelIndex : modelIndex == 20
            ? std::numeric_limits<int>::min() : std::numeric_limits<int>::max();
        check(cs80::body::name(model) != nullptr, "clamped model name");
        for (const auto rate : rates) {
            body.prepare(rate.internal, rate.host); filter.prepare(rate.internal);
            prepares += 2;
            for (std::size_t n = 0; n < std::size(notes); ++n) {
                const auto note = notes[n]; ++matrixCases;
                const auto seed = n % 3 == 0 ? 0u : n % 3 == 1 ? UINT32_MAX : 0x731ac91u;
                // Repeated noteOn without an intervening explicit reset.
                body.noteOn(model, note.key, note.velocity, note.brightness,
                            note.decay, seed, note.size); ++noteOns;
                for (std::size_t i = 0; i < 257; ++i) {
                    const float frequency = frequencies[(i / 17 + n) % std::size(frequencies)];
                    const float colour = controls[(i / 13 + n) % std::size(controls)];
                    const float pressure = controls[(i / 11 + n + 3) % std::size(controls)];
                    const float x = body.tick(frequency, colour, pressure);
                    bodySample(x);
                    if (!std::isfinite(frequency) || frequency <= 0)
                        check(x == 0, "invalid frequency silent");
                    filterSample(filter.tick(x + .1f * std::sin(float(i) * .37f),
                        cutoffs[(i / 16 + n) % std::size(cutoffs)],
                        cutoffs[(i / 19 + n + 2) % std::size(cutoffs)],
                        qs[(i / 23 + n) % std::size(qs)],
                        qs[(i / 29 + n + 3) % std::size(qs)],
                        i % 31 < 15, i % 43 < 21));
                }
                // Interleave explicit resets with repeated-onset cases.
                if (n % 2 == 0) {
                    body.reset(); filter.reset(); resets += 2;
                    for (int i = 0; i < 17; ++i) {
                        const float x = body.tick(440, 1, 1);
                        bodySample(x); check(x == 0, "reset body silent");
                        const float y = filter.tick(0, 1000, 2000, 4, 4, true, true);
                        filterSample(y); check(y == 0, "reset filter silent");
                    }
                }
            }
        }
    }
    // Long enough to execute the 2048-sample mode-renormalization boundary,
    // coefficient refresh and sustained motion at every valid rate/model pair.
    constexpr Rate longRates[] = {{8000,8000}, {44100,44100}, {96000,48000},
        {192000,96000}, {384000,192000}, {1536000,192000}};
    int longCases = 0, copyCases = 0;
    for (int model = 0; model < 20; ++model) {
        for (const auto rate : longRates) {
            ++longCases;
            body.prepare(rate.internal, rate.host); filter.prepare(rate.internal);
            prepares += 2;
            body.noteOn(model, 24, 1, 1, 4, UINT32_MAX, 2.5f); ++noteOns;
            for (int i = 0; i < 4097; ++i) {
                const float pitch = 32.7032f * std::exp2(.8f * std::sin(float(i) * .001f));
                const float x = body.tick(pitch, .5f + .5f * std::sin(float(i) * .003f),
                                          i % 2048 < 1024 ? 0.0f : 1.0f);
                bodySample(x);
                filterSample(filter.tick(x, 16, 2800, 4, 4, true, true));
            }
            // A value-copy outgoing voice must remain independent after the
            // incoming object is reset, prepared and assigned another model.
            auto bodyCopy = body, bodyReference = body;
            auto filterCopy = filter, filterReference = filter;
            body.reset(); filter.reset(); resets += 2;
            body.prepare(8000,8000); filter.prepare(8000); prepares += 2;
            body.noteOn((model + 7) % 20,127,0,0,.25f,0,.5f); ++noteOns;
            ++copyCases;
            for (int i = 0; i < 65; ++i) {
                const float x = bodyCopy.tick(32.7032f, 1, 1);
                const float reference = bodyReference.tick(32.7032f, 1, 1);
                bodySample(x); bodySample(reference);
                check(x == reference, "body copy independent");
                const float y = filterCopy.tickFrozen(x);
                const float yReference = filterReference.tickFrozen(reference);
                filterSample(y); filterSample(yReference);
                check(y == yReference, "frozen filter copy independent");
                bodySample(body.tick(12543.854f, 0, 0));
                filterSample(filter.tick(.1f, 1000, 1000, .5f, .5f, true, false));
            }
        }
    }
    std::printf("{\"matrix_cases\":%d,\"long_cases\":%d,\"copy_cases\":%d,"
                "\"model_choices\":20,\"out_of_range_model_choices\":2,\"matrix_rate_pairs\":14,"
                "\"note_tuples\":9,\"body_samples\":%llu,\"filter_samples\":%llu,"
                "\"prepare_calls\":%llu,\"explicit_reset_calls\":%llu,\"note_on_calls\":%llu,"
                "\"checks\":%llu,\"failures\":%llu,\"body_peak\":%.12g,\"filter_peak\":%.12g}\n",
                matrixCases,longCases,copyCases,(unsigned long long)bodySamples,
                (unsigned long long)filterSamples,(unsigned long long)prepares,
                (unsigned long long)resets,(unsigned long long)noteOns,
                (unsigned long long)checks,(unsigned long long)failures,bodyPeak,filterPeak);
    return failures ? 1 : 0;
}
